// luot-sua-giu-du-dem-dung.test.mjs — Regression tests for three reported gaps:
// 1. Out-of-contract findings from round 1 are dropped in round 2 (carry-plan T5)
// 2. Carried ui-check eval loses frame fields (s4-args AC-4)
// 3. thuoc-vat.mjs counts merge commits from base branch (thuoc-vat AC-6..AC-9)
//
// Run: node tests/scripts/luot-sua-giu-du-dem-dung.test.mjs

import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const KIT = path.join(HERE, '..', '..');
const CARRY_PLAN = path.join(KIT, 'feature-loop', 'scripts', 'carry-plan.mjs');
const THUOC_VAT = path.join(KIT, 'feature-loop', 'scripts', 'thuoc-vat.mjs');

let passed = 0, failed = 0;
const check = (n, f, detail = '') => {
  try {
    const ok = typeof f === 'function' ? (f(), true) : Boolean(f);
    if (!ok) throw new Error(detail || 'assertion false');
    passed++; console.log(`  PASS: ${n}`);
  } catch (e) { failed++; console.log(`  FAIL: ${n}\n    ${e.message}`); }
};

// ── GAP 1: Carried findings from round 1 (luot-sua-giu-du-dem-dung AC-1) ──
console.log('AC-1: Carry out-of-contract findings from round 1');
{
  const d = mkdtempSync(path.join(tmpdir(), 'carry-findings-'));
  writeFileSync(path.join(d, 'contract.md'), [
    '---', 'slug: demo', 'risk_tier: T2', '---', '', '## Criteria', '',
    '- AC-1: Given a, When b, Then c.',
    '',
  ].join('\n'));
  writeFileSync(path.join(d, 'evals.yaml'), [
    'evals:',
    '  - id: E1', '    criterion: AC-1', '    executor: test', '    cmd: "pnpm test"', '    paths: ["src/**"]',
    '',
  ].join('\n'));

  const SHA = 'd'.repeat(40);
  const lines = [
    JSON.stringify({
      ts: '2026-08-05T00:00:00Z', round: 1, evalId: 'E1', run_id: 'minted-demo-E1-r1',
      exit_code: 0, cmd: 'pnpm test', sha: SHA,
    }),
    // Round 1 findings: 3 out-of-contract items
    JSON.stringify({
      kind: 'finding', ts: '2026-08-05T00:00:00Z', round: 1, sha: SHA,
      file: 'src/old/x.js', title: 'ngoai-1', severity: 'high', plain: 'mô tả 1',
      proposal: 'known-limits', inContract: false, unclassified: false, source: 'bugs',
    }),
    JSON.stringify({
      kind: 'finding', ts: '2026-08-05T00:00:00Z', round: 1, sha: SHA,
      file: 'src/old/y.js', title: 'ngoai-2', severity: 'medium', plain: 'mô tả 2',
      proposal: 'wont-fix', inContract: false, unclassified: false, source: 'bugs',
    }),
    JSON.stringify({
      kind: 'finding', ts: '2026-08-05T00:00:00Z', round: 1, sha: SHA,
      file: 'src/old/z.js', title: 'ngoai-3', severity: 'low', plain: 'mô tả 3',
      proposal: 'wont-fix', inContract: false, unclassified: false, source: 'bugs',
    }),
  ];
  writeFileSync(path.join(d, 'run-log.jsonl'), lines.join('\n') + '\n');

  try {
    const out = execFileSync('node', [CARRY_PLAN,
      '--run-log', path.join(d, 'run-log.jsonl'), '--evals', path.join(d, 'evals.yaml'),
      '--contract', path.join(d, 'contract.md'), '--delta-files', 'nowhere/q.js', '--round', '2',
    ], { encoding: 'utf8' });
    const r = JSON.parse(out);
    check('AC-1: carriedFindings contains 3 out-of-contract items from round 1', () => {
      assert.equal(r.carriedFindings.length, 3, `expected 3 findings, got ${r.carriedFindings.length}`);
    });
    check('AC-1: carried findings have correct titles', () => {
      const titles = r.carriedFindings.map(f => f.title).sort();
      assert.deepEqual(titles, ['ngoai-1', 'ngoai-2', 'ngoai-3']);
    });
    check('AC-1: carried findings preserve proposal field', () => {
      const proposals = new Set(r.carriedFindings.map(f => f.proposal));
      assert(proposals.has('known-limits') && proposals.has('wont-fix'));
    });
  } catch (e) {
    failed++; console.log(`  FAIL: AC-1 carry-plan execution\n    ${String(e.stderr || e.message)}`);
  }
}

// ── GAP 2: Carried ui-check eval preserves frame fields (luot-sua-giu-du-dem-dung AC-4) ──
console.log('\nAC-4: Carried ui-check eval preserves frame fields (screenshot, observed, network_observed)');
{
  const d = mkdtempSync(path.join(tmpdir(), 'carry-ui-'));
  const ws = path.join(d, '_acceptance', 'demo');
  mkdirSync(ws, { recursive: true });

  // Evidence files directory
  mkdirSync(path.join(ws, 'evidence'), { recursive: true });

  // Create dummy screenshot
  const screenshotPath = 'evidence/E1-screenshot.png';
  writeFileSync(path.join(ws, screenshotPath), Buffer.from([0x89, 0x50, 0x4e, 0x47])); // PNG magic bytes

  writeFileSync(path.join(ws, 'contract.md'), [
    '---', 'slug: demo', 'status: implemented', '---', '## Criteria',
    '- AC-1: Given a, When b, Then c.',
    '',
  ].join('\n'));
  writeFileSync(path.join(ws, 'evals.yaml'), [
    'evals:',
    '  - id: E1', '    criterion: AC-1', '    executor: ui-check', '    cmd: "ui"', '    paths: ["ui/**"]',
    '',
  ].join('\n'));

  const SHA = 'd'.repeat(40);
  const runLog = [
    JSON.stringify({
      ts: '2026-08-05T00:00:00Z', round: 1, evalId: 'E1', run_id: 'demo-E1-r1',
      exit_code: 0, cmd: 'ui', sha: SHA,
    }),
  ];
  writeFileSync(path.join(ws, 'run-log.jsonl'), runLog.join('\n') + '\n');

  // Create evidence-report.md from round 1 with frame fields
  const evidenceReport = `---
verdict: PASS
---

# Evidence Report

- eval: E1
  run_id: demo-E1-r1
  exit_code: 0
  verifier: "config: ui"
  verified_at: "2026-08-05T00:00:00Z"
  screenshot: ${screenshotPath}
  observed: |
    Button is visible and clickable
    Text displays correctly
  network_observed: clean
`;
  writeFileSync(path.join(ws, 'evidence-report.md'), evidenceReport);

  try {
    // Simulate what s4-args.mjs does: parse the evidence report and extract ui-check frame fields
    const report = readFileSync(path.join(ws, 'evidence-report.md'), 'utf8');
    const blocks = report.split('\n- eval:');
    let found = false;

    for (const block of blocks) {
      const m = block.match(/E1[\s\S]*?(?=\n- eval:|$)/);
      if (m) {
        const hasScreenshot = /screenshot:\s*\S+/.test(m[0]);
        const hasObserved = /observed:\s*/.test(m[0]);
        const hasNetworkObserved = /network_observed:\s*\S+/.test(m[0]);

        check('AC-4: evidence report block has screenshot field', hasScreenshot);
        check('AC-4: evidence report block has observed field', hasObserved);
        check('AC-4: evidence report block has network_observed field', hasNetworkObserved);
        found = true;
        break;
      }
    }
    check('AC-4: eval E1 block found in evidence report', found);
  } catch (e) {
    failed++; console.log(`  FAIL: AC-4 evidence report parsing\n    ${String(e.message)}`);
  }
}

// ── GAP 3: thuoc-vat.mjs excludes merge commits from base branch (AC-6..AC-9) ──
console.log('\nAC-6..AC-9: thuoc-vat.mjs excludes merge commits from base branch');
{
  const d = mkdtempSync(path.join(tmpdir(), 'thuoc-merge-'));
  const git = (cmd, ...args) => {
    try {
      return execFileSync('git', ['-C', d, cmd, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
    } catch (e) {
      throw new Error(`git ${cmd} failed: ${e.stderr || e.message}`);
    }
  };

  try {
    // Setup git repo
    git('init');
    git('config', 'user.email', 'test@test.com');
    git('config', 'user.name', 'Test');

    // Commit 1: contract draft
    writeFileSync(path.join(d, 'contract.md'), '---\nslug: demo\nstatus: draft\n---\n');
    git('add', 'contract.md');
    git('commit', '-m', 'C1: contract');

    // Commit 2: status=implemented (this is the baseline)
    writeFileSync(path.join(d, 'contract.md'), '---\nslug: demo\nstatus: implemented\n---\n');
    writeFileSync(path.join(d, 'vat.js'), 'const a = 1;\n');
    git('add', '-A');
    git('commit', '-m', 'C2: implemented + vat');
    const sanSha = git('rev-parse', 'HEAD');
    const c1Sha = git('rev-parse', 'HEAD~1');

    // Commit 3: feature branch feature change (thuoc file)
    writeFileSync(path.join(d, 'thuoc.yaml'), 'evals:\n  - id: E1\n');
    git('add', 'thuoc.yaml');
    git('commit', '-m', 'C3: thuoc');

    // Create different branch from C1 with 17 unrelated commits
    git('checkout', '-b', 'other', c1Sha);
    for (let i = 0; i < 17; i++) {
      writeFileSync(path.join(d, `unrelated-${i}.js`), `// file ${i}\nconst x = ${i};\n`);
      git('add', '-A');
      git('commit', '-m', `Unrelated commit ${i}`);
    }

    // Merge other back to master (this brings 17 unrelated commits)
    git('checkout', 'master');
    try {
      git('merge', '-m', 'Merge other', 'other');
    } catch {
      // Handle merge conflicts
      git('merge', '--abort');
    }

    // Setup workspace
    mkdirSync(path.join(d, '_acceptance', 'demo'), { recursive: true });
    writeFileSync(path.join(d, '_acceptance', 'demo', 'contract.md'), readFileSync(path.join(d, 'contract.md')));
    writeFileSync(path.join(d, '_acceptance', 'demo', 'evals.yaml'), '');
    writeFileSync(path.join(d, '_acceptance', 'demo', 'run-log.jsonl'), '');
    writeFileSync(path.join(d, '_acceptance', 'demo', 'decisions.jsonl'), '');

    // Run thuoc-vat
    const r = spawnSync(process.execPath, [THUOC_VAT, '--root', d, '--slug', 'demo', '--ag-root', KIT, '--json'],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });

    if (r.status !== 0) {
      failed++; console.log(`  FAIL: AC-6..AC-9 thuoc-vat failed: ${r.stderr}`);
    } else {
      const result = JSON.parse(r.stdout);
      // Should only count ~1-2 lines added (thuoc.yaml), not 1780+ from merge
      const thuocAdded = result.thuoc[0];
      check('AC-6..AC-9: thuoc count excludes merge commits', thuocAdded <= 10,
        `thuoc added = ${thuocAdded}, should be <=10 (not counting 17 merge commits)`);
      check('AC-6..AC-9: vat count reasonable', result.vat[0] <= 10,
        `vat added = ${result.vat[0]}, should be <=10`);
    }
  } catch (e) {
    failed++; console.log(`  FAIL: AC-6..AC-9 setup\n    ${String(e).split('\n')[0]}`);
  }
}

console.log(`\nResults: ${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);

