// thuoc-vat-merge-detailed.test.mjs — Detailed test for merge commit counting
// Reproduces the exact scenario from luot-sua-giu-du-dem-dung: 17 unrelated commits
// merged into feature branch, then verify thuoc count doesn't include merge files.

import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, mkdirSync } from 'node:fs';
